interface Visitor<R> {
    R visitNum(int n);
    R visitAdd(Expr a, Expr b);
}
interface Expr { <R> R accept(Visitor<R> v); }
public class Vis {
    public static void main(String[] args) {
        Expr two = new Expr() { public <R> R accept(Visitor<R> v) { return v.visitNum(2); } };
        Expr three = new Expr() { public <R> R accept(Visitor<R> v) { return v.visitNum(3); } };
        Expr sum = new Expr() { public <R> R accept(Visitor<R> v) { return v.visitAdd(two, three); } };
        Visitor<Integer> eval = new Visitor<>() {
            public Integer visitNum(int n) { return n; }
            public Integer visitAdd(Expr a, Expr b) { return a.accept(this) + b.accept(this); }
        };
        System.out.println(sum.accept(eval));
    }
}

