public class Cb {
    interface Listener { void onEvent(String e); }
    private final List<Listener> listeners = new ArrayList<>();
    void add(Listener l) { listeners.add(l); }
    void fire(String e) { listeners.forEach(l -> l.onEvent(e)); }
    public static void main(String[] args) {
        Cb bus = new Cb();
        StringBuilder log = new StringBuilder();
        bus.add(e -> log.append("1").append(e));
        bus.add(new Listener() {
            public void onEvent(String e) { log.append("2").append(e.toUpperCase()); }
        });
        bus.fire("x");
        System.out.println(log);
    }
}

